		G: Object.assign({
			overlap: false,
			pad: 0.3,
			rankdir: config.rankdir,
			layout: config.layout,
			bgcolor: config.backgroundColor
		}, graphVizOptions.G),
		// Edge
		E: Object.assign({
			color: config.edgeColor
		}, graphVizOptions.E),
		// Node
		N: Object.assign({
			fontname: config.fontName,
			fontsize: config.fontSize,
